# QM I exercise sheets VII-IX (HS25 set, Gaberdiel; the HS26 course uses the same sheets).
# Statements and solutions follow the official sheets and solutions (Exercises N.pdf, Solutions N.pdf), condensed.
from qm_sheet_lib import S, Q

S(7, 'Oscillators in 2D, coherent states, degeneracies', '2025-11-05', [
 Q(1, '2D harmonic oscillator', 'harmonic-oscillator-elevator', ['qm-ho-L1', 'qm-ho-L4', 'qm-ho-D5', 'qm-ho-c4'],
   r'$H=\frac{\hbar\omega}{2}\left(-\partial_x^2-\partial_y^2+x^2+y^2\right)$ (dimensionless coordinates). (i) Introduce $a,a^\dagger,b,b^\dagger$ and show $H=\hbar\omega(a^\dagger a+b^\dagger b+1)$; give their commutators. (ii) Find the eigenstates and the vacuum wave function $\psi_0(x,y)$. (iii) Show that $H$ is invariant under $\binom{a}{b}\to R(\varphi)\binom{a}{b}$, $R=\begin{pmatrix}\cos\varphi&-\sin\varphi\\ \sin\varphi&\cos\varphi\end{pmatrix}$ (same on $a^\dagger,b^\dagger$); what does it do to $x,y$? (iv) Find the generator $J$: $[J,a]=\frac{d}{d\varphi}a(\varphi)|_0$, $[J,b]=\frac{d}{d\varphi}b(\varphi)|_0$. (v) Show $[H,J]=0$ and diagonalise $J$ on the states with $E\le2\hbar\omega$.',
   [('(i) Two independent 1D oscillators.', r'$a=\frac1{\sqrt2}(x+\partial_x)$, $a^\dagger=\frac1{\sqrt2}(x-\partial_x)$, same for $b$ with $y$. $[a,a^\dagger]=[b,b^\dagger]=1$, all other commutators vanish. $a^\dagger a=\frac12(x^2-1-\partial_x^2)$, hence $H=\hbar\omega(a^\dagger a+b^\dagger b+1)$.'),
    ('(ii) Eigenstates and vacuum.', r'$|m,n\rangle=\frac{(a^\dagger)^m(b^\dagger)^n}{\sqrt{m!\,n!}}|0,0\rangle$, $E=\hbar\omega(m+n+1)$ (degeneracy $N+1$ at $E=\hbar\omega(N+1)$). $a|0\rangle=b|0\rangle=0$ gives $(x+\partial_x)\psi_0=(y+\partial_y)\psi_0=0$: $\psi_0=\pi^{-1/2}e^{-(x^2+y^2)/2}$.'),
    ('(iii) The symmetry.', r'$H=\hbar\omega\,(a^\dagger\ b^\dagger)\binom ab+\hbar\omega$ and $R^TR=I$, so $H$ is invariant. Since $x=(a+a^\dagger)/\sqrt2$, $y=(b+b^\dagger)/\sqrt2$, $x,y$ are rotated by the same $R(\varphi)$: rotational symmetry of the isotropic oscillator.'),
    ('(iv) Generator.', r'$\frac{d}{d\varphi}a(\varphi)|_0=-b$, $\frac{d}{d\varphi}b(\varphi)|_0=a$; $J=a^\dagger b-b^\dagger a$ does it ($[a^\dagger b,a]=-b$, $[-b^\dagger a,b]=a$). $iJ$ is (up to $\hbar$) the angular momentum $L_z$.'),
    ('(v) $[H,J]=0$ and the matrix of $J$.', r'$[H,a^\dagger b]=a^\dagger(-\hbar\omega b)+\hbar\omega a^\dagger b=0$, same for $b^\dagger a$. $J|m,n\rangle=\sqrt{(m+1)n}|m+1,n-1\rangle-\sqrt{m(n+1)}|m-1,n+1\rangle$. On $\{|0,0\rangle,|1,0\rangle,|0,1\rangle\}$: $J=\begin{pmatrix}0&0&0\\0&0&1\\0&-1&0\end{pmatrix}$, eigenvectors $|0,0\rangle$ (0), $\frac1{\sqrt2}(|1,0\rangle\pm i|0,1\rangle)$ ($\pm i$).')],
   [r'$H=\hbar\omega(a^\dagger a+b^\dagger b+1)$ with correct commutators', r'$\psi_0=\pi^{-1/2}e^{-(x^2+y^2)/2}$', r'invariance from $R^TR=I$, rotation of $(x,y)$', r'$J=a^\dagger b-b^\dagger a$, $[H,J]=0$', r'eigenvalues $0,\pm i$ on $E\le2\hbar\omega$']),
 Q(2, 'Coherent states', 'harmonic-oscillator-elevator', ['qm-ho-L3', 'qm-ho-D1', 'qm-ho-c3', 'qm-ho-Q1', 'qm-fu-D4'],
   r'$a|\alpha\rangle=\alpha|\alpha\rangle$, $\langle\alpha|\alpha\rangle=1$. (i) Show $|\alpha\rangle=e^{-|\alpha|^2/2}e^{\alpha a^\dagger}|0\rangle$. (ii) Show $|\alpha\rangle(t)=e^{-i\omega t/2}|\alpha e^{-i\omega t}\rangle$. (iii) Compute $\langle x\rangle(t)$, $\langle p\rangle(t)$ and compare with the classical motion. (iv) Show $\Delta x\Delta p=\hbar/2$. (v) Show completeness $\int\frac{d\alpha^*d\alpha}{2\pi i}|\alpha\rangle\langle\alpha|=I$. (vi) Show that $\langle x|\alpha\rangle$ is a Gaussian.',
   [('(i) Expand in $|n\rangle$.', r'$a\sum c_n|n\rangle=\sum c_{n+1}\sqrt{n+1}|n\rangle=\alpha\sum c_n|n\rangle$ gives $c_n=\frac{\alpha^n}{\sqrt{n!}}c_0$, i.e. $|\alpha\rangle=c_0e^{\alpha a^\dagger}|0\rangle$; normalisation $|c_0|^2e^{|\alpha|^2}=1$.'),
    ('(ii) Time evolution.', r'$e^{-iHt/\hbar}|n\rangle=e^{-i\omega(n+\frac12)t}|n\rangle$, so $\alpha^n\to(\alpha e^{-i\omega t})^n$ and a global $e^{-i\omega t/2}$: again coherent with $\alpha(t)=\alpha e^{-i\omega t}$.'),
    ('(iii) Expectation values.', r'$x=\sqrt{\frac{\hbar}{2m\omega}}(a+a^\dagger)$, $p=-i\sqrt{\frac{m\hbar\omega}2}(a-a^\dagger)$: $\langle x\rangle=\sqrt{\frac{2\hbar}{m\omega}}|\alpha|\cos(\omega t-\phi_0)$, $\langle p\rangle=-\sqrt{2m\hbar\omega}|\alpha|\sin(\omega t-\phi_0)$: the classical oscillation (Ehrenfest is exact for the oscillator, $\langle V^\prime(x)\rangle=V^\prime(\langle x\rangle)$).'),
    ('(iv) Minimal uncertainty.', r'With $aa^\dagger=a^\dagger a+1$: $\langle x^2\rangle=\frac{\hbar}{2m\omega}(1+2|\alpha|^2+\alpha^2+\bar\alpha^2)$, so $(\Delta x)^2=\frac{\hbar}{2m\omega}$, $(\Delta p)^2=\frac{m\hbar\omega}2$, $\Delta x\Delta p=\hbar/2$ at all times.'),
    ('(v) Completeness.', r'Polar coordinates $\alpha=re^{i\theta}$, $d\alpha^*d\alpha=2i\,r\,dr\,d\theta$: the $\theta$ integral gives $2\pi\delta_{nm}$, then $\frac{2}{n!}\int_0^\infty e^{-r^2}r^{2n+1}dr=\frac{\Gamma(n+1)}{n!}=1$: $\sum_n|n\rangle\langle n|=I$.'),
    ('(vi) Wave function.', r'$\left(\sqrt{\frac{m\omega}{2\hbar}}x+\sqrt{\frac{\hbar}{2m\omega}}\frac{d}{dx}\right)\psi_\alpha=\alpha\psi_\alpha$ gives $\psi_\alpha=A\exp\left[-\frac{m\omega}{2\hbar}\left(x-\sqrt{\frac{2\hbar}{m\omega}}\alpha\right)^2\right]$. For $\alpha=0$ it is the ground state, which we already knew is Gaussian.')],
   [r'recursion $c_n=\alpha^n c_0/\sqrt{n!}$ and normalisation', r'$\alpha(t)=\alpha e^{-i\omega t}$', r'classical $\langle x\rangle(t)$, $\langle p\rangle(t)$', r'$\Delta x\Delta p=\hbar/2$', r'completeness via the angular integral', r'Gaussian centred at $\sqrt{2\hbar/m\omega}\,\alpha$']),
 Q(3, 'Degeneracies', 'harmonic-oscillator-elevator', ['qm-ho-L4', 'qm-ho-c4', 'qm-ho-D6'],
   r'$D_n^k$ = number of ways to write $n$ as a sum of $k$ non-negative integers; $F^k(s)=\sum_nD_n^ks^n$, $|s|<1$. (i) Show $F^k(s)=\sum_{n_1}\cdots\sum_{n_k}s^{n_1+\dots+n_k}$. (ii) Deduce $F^k=(1-s)^{-k}$ and $D_n^k=\binom{n+k-1}{n}$. (iii) Degeneracies of the isotropic oscillator in 2D and 3D.',
   [('(i) Product of series.', r'$\prod_j\left(\sum_{n_j}s^{n_j}\right)=\sum_nc_ns^n$ where $c_n$ counts the terms with $n_1+\dots+n_k=n$, i.e. $c_n=D_n^k$.'),
    ('(ii) Geometric series.', r'Each factor is $(1-s)^{-1}$, so $F^k=(1-s)^{-k}=\sum_n\binom{n+k-1}{n}s^n$ (binomial series or $\frac{1}{(k-1)!}\frac{d^{k-1}}{ds^{k-1}}\frac1{1-s}$).'),
    ('(iii) Oscillators.', r'$E=\hbar\omega(N+\frac k2)$ with $N=n_1+\dots+n_k$: 2D $D_N^2=N+1$, 3D $D_N^3=\frac{(N+1)(N+2)}2$ (1, 3, 6, 10, ...).')],
   [r'$c_n=D_n^k$ by counting', r'$(1-s)^{-k}$ and the binomial coefficient', r'$N+1$ and $(N+1)(N+2)/2$']),
])

S(8, 'Angular momentum, so(4), su(2) in the 2D oscillator', '2025-11-12', [
 Q(1, 'Angular momentum', 'angular-momentum-spin', ['qm-am-L1', 'qm-am-D1', 'qm-am-D4', 'qm-am-c2', 'qm-am-b2'],
   r'$\vec L=\vec r\wedge\vec p$, $L_i=\varepsilon_{ijk}r_jp_k$. (i) With $[r_i,p_j]=i\hbar\delta_{ij}$ derive $[L_i,L_j]=i\hbar\varepsilon_{ijk}L_k$ and $[L_3,\vec L^2]=0$. (ii) Evaluate $[L_3,L_1L_2+L_2L_1]$ and deduce $\langle l,m|L_1^2|l,m\rangle=\langle l,m|L_2^2|l,m\rangle=\frac{\hbar^2}2[l(l+1)-m^2]$. Hint: for an eigenstate $|\psi\rangle$ of a self-adjoint $A$, $\langle\psi|[A,B]|\psi\rangle=0$.',
   [('(i) The algebra.', r'$[L_i,L_j]=\varepsilon_{ikl}\varepsilon_{jmn}[r_kp_l,r_mp_n]=i\hbar(-\varepsilon_{ikl}\varepsilon_{jln}r_kp_n+\varepsilon_{ikl}\varepsilon_{jmk}r_mp_l)$; with $\varepsilon\varepsilon=\delta\delta-\delta\delta$ this is $i\hbar(r_ip_j-r_jp_i)=i\hbar\varepsilon_{ijk}L_k$, since $\varepsilon_{ijk}L_k=r_ip_j-r_jp_i$.'),
    (r'$[L_3,\vec L^2]$.', r'$[L_3,L_1^2+L_2^2]=[L_3,L_1]L_1+L_1[L_3,L_1]+[L_3,L_2]L_2+L_2[L_3,L_2]=i\hbar(L_2L_1+L_1L_2-L_1L_2-L_2L_1)=0$.'),
    ('(ii) The hint.', r'$A|\psi\rangle=a|\psi\rangle$ with $a$ real: $\langle\psi|AB-BA|\psi\rangle=(a-a)\langle\psi|B|\psi\rangle=0$.'),
    ('(ii) The expectation values.', r'$[L_3,L_1L_2+L_2L_1]=2i\hbar(L_2^2-L_1^2)$, so in $|l,m\rangle$: $\langle L_1^2\rangle=\langle L_2^2\rangle$. With $L_1^2+L_2^2=\vec L^2-L_3^2$: each is $\frac{\hbar^2}2[l(l+1)-m^2]$ (and $\langle L_{1,2}\rangle=0$, so these are the variances).')],
   [r'$\varepsilon$-identity to get $i\hbar\varepsilon_{ijk}L_k$', r'$[L_3,\vec L^2]=0$', r'proof of the hint', r'$[L_3,L_1L_2+L_2L_1]=2i\hbar(L_2^2-L_1^2)$', r'$\frac{\hbar^2}{2}[l(l+1)-m^2]$']),
 Q(2, 'SO(4)', 'hydrogen-lamp', ['qm-hl-L2', 'qm-hl-D4', 'qm-hl-b2', 'qm-am-L1'],
   r'so(4) = tangent vectors at the identity of paths in SO(4). (i) Describe so(4) as a space of matrices. (ii) Find a basis $A_i,B_i$ with $[A_i,A_j]=\varepsilon_{ijk}A_k$, $[B_i,B_j]=\varepsilon_{ijk}A_k$, $[A_i,B_j]=\varepsilon_{ijk}B_k$. (iii) Show so(4) $\cong$ su(2) $\oplus$ su(2).',
   [('(i) Antisymmetric matrices.', r'$\gamma^T\gamma=I$ gives $\dot\gamma(0)^T+\dot\gamma(0)=0$; conversely $e^{tM}$ for antisymmetric $M$ is in SO(4). So so(4) = real antisymmetric $4\times4$ matrices, 6-dimensional.'),
    ('(ii) Basis.', r'$A_i$: rotations in the 3D block $(1,2,3)$, $(A_i)_{jk}=-\varepsilon_{ijk}$ ($A_1$ rotates in the 2-3 plane, etc.); $B_i$: the "boosts" mixing coordinate $i$ with the 4th, $(B_i)_{4i}=1$, $(B_i)_{i4}=-1$. Compute $[A_1,A_2]=A_3$, $[B_1,B_2]=A_3$, $[A_1,B_2]=B_3$, $[A_1,B_3]=-B_2$, $[A_1,B_1]=0$; the rest follows by cyclic permutation of $1,2,3$.'),
    ('(iii) Two commuting su(2).', r'$X_i=\frac12(A_i+B_i)$, $Y_i=\frac12(A_i-B_i)$: $[X_i,X_j]=\varepsilon_{ijk}X_k$, $[Y_i,Y_j]=\varepsilon_{ijk}Y_k$, $[X_i,Y_j]=0$. In hydrogen these are $\frac12(\vec L\pm\vec D)$ built from $\vec L$ and the Runge-Lenz vector: the origin of the $n^2$ degeneracy.')],
   [r'so(4) = antisymmetric matrices, dim 6', r'explicit $A_i,B_i$ and the commutators', r'$X=\frac12(A+B)$, $Y=\frac12(A-B)$ commute', r'link to $\vec L$ and Runge-Lenz in hydrogen']),
 Q(3, 'Representations of su(2) and the 2D oscillator', 'harmonic-oscillator-elevator', ['qm-ho-L4', 'qm-ho-D5', 'qm-am-L1', 'qm-am-D2', 'qm-ho-c4'],
   r'$J_3=\frac12(a^\dagger a-b^\dagger b)$, $J_+=a^\dagger b$, $J_-=b^\dagger a$. (i) Show $[J_3,J_\pm]=\pm J_\pm$, $[J_+,J_-]=2J_3$. (ii) Show $\vec J^2=\frac N2(\frac N2+1)$, $N=N_a+N_b$. (iii) Give $J_\pm,J_3$ on $|n_a,n_b\rangle$. (iv) With $j=\frac{n_a+n_b}2$, $m=\frac{n_a-n_b}2$ get the standard su(2) form and $|j,m\rangle=\frac{(a^\dagger)^{j+m}(b^\dagger)^{j-m}}{\sqrt{(j+m)!(j-m)!}}|0,0\rangle$. (v) Show the $J$’s commute with $a^\dagger a+b^\dagger b$.',
   [('(i) Commutators.', r'Using $[a,a^\dagger]=1$ and that $a$’s commute with $b$’s: $2[J_3,J_+]=a^\dagger b+a^\dagger b$, $2[J_3,J_-]=-2b^\dagger a$, $[J_+,J_-]=a^\dagger(1+b^\dagger b)a-b^\dagger(1+a^\dagger a)b=a^\dagger a-b^\dagger b=2J_3$.'),
    (r'(ii) $\vec J^2$.', r'$\vec J^2=\frac14(N_a-N_b)^2+\frac12\left(N_a(1+N_b)+N_b(1+N_a)\right)=\frac14(N_a+N_b)^2+\frac12(N_a+N_b)=\frac N2\left(\frac N2+1\right)$.'),
    ('(iii)-(iv) Action and relabelling.', r'$J_+|n_a,n_b\rangle=\sqrt{n_b(n_a+1)}|n_a+1,n_b-1\rangle$, $J_-|n_a,n_b\rangle=\sqrt{n_a(n_b+1)}|n_a-1,n_b+1\rangle$, $J_3=\frac12(n_a-n_b)$. With $n_a=j+m$, $n_b=j-m$: $J_\pm|j,m\rangle=\sqrt{j(j+1)-m(m\pm1)}|j,m\pm1\rangle$, $J_3|j,m\rangle=m|j,m\rangle$: the spin-$j$ representation (Schwinger representation).'),
    ('(v) Hidden symmetry.', r'$[J_+,N_a+N_b]=[a^\dagger,N_a]b+a^\dagger[b,N_b]=-a^\dagger b+a^\dagger b=0$, same for $J_-$, $J_3$. The level $E=\hbar\omega(N+1)$ is the spin $j=N/2$ multiplet: dimension $N+1$, exactly its degeneracy.')],
   [r'su(2) commutators from $[a,a^\dagger]=1$', r'$\vec J^2=\frac N2(\frac N2+1)$', r'standard $J_\pm$ matrix elements', r'degenerate level = spin $N/2$ irrep']),
])

S(9, 'sech² potential, discrete spectra, Pauli matrices, su(3)', '2025-11-19', [
 Q(1, 'The sech² potential', 'harmonic-oscillator-elevator', ['qm-ho-D3', 'qm-ho-L1', 'qm-tunnel-L4'],
   r'$H=-\frac{\hbar^2}{2m}\partial_x^2+V$, $V=-\frac{\hbar^2}{m}\mathrm{sech}^2x$. (i) Sketch $V$ and the expected ground state. (ii) Show $A^\dagger A\psi=(\epsilon+1)\psi$ with $\epsilon=2mE/\hbar^2$, $A=\partial_x+\tanh x$. (iii) Show $\epsilon\ge-1$ and find $\psi_0$ (what is $A\psi_0$?).',
   [('(i) Sketch.', r'Symmetric well with minimum $-\hbar^2/m$ at $x=0$, going to 0 at $\pm\infty$. Ground state: even, no node, localised in the well, decaying outside.'),
    ('(ii) Factorisation.', r'$A^\dagger=-\partial_x+\tanh x$, $A^\dagger A\psi=-\psi^{\prime\prime}+(\tanh^2x-\tanh^\prime x)\psi=-\psi^{\prime\prime}+(1-2\,\mathrm{sech}^2x)\psi=\frac{2m}{\hbar^2}H\psi+\psi=(\epsilon+1)\psi$.'),
    ('(iii) Bound and ground state.', r'$\langle\chi|A^\dagger A|\chi\rangle=\|A\chi\|^2\ge0$ gives $\epsilon\ge-1$, saturated when $A\psi_0=0$: $\psi_0^\prime=-\tanh x\,\psi_0$, $\psi_0=\frac{1}{\sqrt2\cosh x}$, $E_0=-\frac{\hbar^2}{2m}$.')],
   [r'shape of $V$ and an even, nodeless $\psi_0$', r'$\tanh^2-\tanh^\prime=1-2\,\mathrm{sech}^2$', r'$A^\dagger A\ge0\Rightarrow\epsilon\ge-1$', r'$\psi_0=1/(\sqrt2\cosh x)$']),
 Q(2, 'Discreteness of the spectrum', 'formalism-and-uncertainty', ['qm-fu-L2', 'qm-fu-L1'],
   r'$Z(\beta)=\mathrm{tr}\,e^{-\beta H}$ for $H=-\frac{\hbar^2}{2m}\nabla^2+V(q)$ in $d$ dimensions. (i) Argue that $Z<\infty$ implies a discrete spectrum. (ii) With Golden-Thompson $\mathrm{tr}\,e^{A+B}\le\mathrm{tr}(e^Ae^B)$ show $Z(\beta)\le\frac{1}{(2\pi\hbar)^d}\int d^dq\,d^dp\,e^{-\beta(p^2/2m+V)}=Z_{\rm classical}$. (iii) Give a sufficient condition on $V$; show the spectrum of $-\frac{\hbar^2}{2m}\nabla^2+\nu\|q\|^\alpha$ is discrete.',
   [('(i) Why finite means discrete.', r'A continuum would be summed over a continuum of values with infinite weight: e.g. $V=0$ gives $\int d^dp\,e^{-\beta p^2/2m}\langle p|p\rangle=\infty$ ($\delta(0)$). Rigorously: $e^{-\beta H}$ is then trace class, its spectrum is discrete, hence that of $H$.'),
    ('(ii) Golden-Thompson.', r'$Z\le\int d^dq\,\langle q|e^{-\beta T}|q\rangle e^{-\beta V(q)}$ ($V$ diagonal in $|q\rangle$); inserting momentum states with $\langle q|p\rangle=(2\pi\hbar)^{-d/2}e^{ip\cdot q/\hbar}$: $\langle q|e^{-\beta T}|q\rangle=(2\pi\hbar)^{-d}\int d^dp\,e^{-\beta p^2/2m}$.'),
    ('(iii) Criterion and example.', r'Sufficient: $\int d^dq\,e^{-\beta V(q)}<\infty$ for all $\beta>0$. For $\nu\|q\|^\alpha$: $\mathrm{vol}(S^{d-1})\int_0^\infty r^{d-1}e^{-\beta\nu r^\alpha}dr=\frac{\mathrm{vol}(S^{d-1})}{\alpha(\beta\nu)^{d/\alpha}}\Gamma(\frac d\alpha)<\infty$: discrete (e.g. the oscillator, $\alpha=2$).')],
   [r'finite trace $\Rightarrow$ discrete spectrum', r'momentum-basis evaluation of $\langle q|e^{-\beta T}|q\rangle$', r'criterion $\int e^{-\beta V}<\infty$', r'Gamma-function integral for $\|q\|^\alpha$']),
 Q(3, 'Pauli matrices and rotations', 'angular-momentum-spin', ['qm-am-L2', 'qm-am-D3', 'qm-am-c1', 'qm-am-Q1'],
   r'Show that $U(\omega\vec n)=\exp(-i\frac\omega2\vec n\cdot\vec\sigma)\in SU(2)$ is a rotation by $\omega$ about $\vec n$: (i) $\sigma_j\sigma_k=\delta_{jk}I+i\varepsilon_{jkl}\sigma_l$; (ii) $U=\cos\frac\omega2I-i\sin\frac\omega2\,\vec n\cdot\vec\sigma$; (iii) with $\tilde x=\vec x\cdot\vec\sigma$, compute $\tilde x^\prime=U\tilde xU^\dagger$.',
   [('(i) Products.', r'Check $\sigma_j^2=I$ and $\sigma_1\sigma_2=i\sigma_3$ (cyclic); hence $(\vec x\cdot\vec\sigma)(\vec y\cdot\vec\sigma)=(\vec x\cdot\vec y)I+i(\vec x\times\vec y)\cdot\vec\sigma$ and $(\vec n\cdot\vec\sigma)^2=I$.'),
    ('(ii) Exponential.', r'Split the series into even powers ($I$) and odd powers ($\vec n\cdot\vec\sigma$): $\cos\frac\omega2I-i\sin\frac\omega2\,\vec n\cdot\vec\sigma$. Note $U(2\pi\vec n)=-I$: spinors change sign under a full turn.'),
    ('(iii) The rotation.', r'$\tilde x^\prime=\left(\cos\omega\,\vec x-\sin\omega\,\vec x\times\vec n+(1-\cos\omega)(\vec x\cdot\vec n)\vec n\right)\cdot\vec\sigma$: Rodrigues’ formula for a rotation by $\omega$ about $\vec n$ (check with $\vec n=\hat e_3$: $\hat e_1\to\cos\omega\,\hat e_1+\sin\omega\,\hat e_2$).')],
   [r'$\sigma_j\sigma_k=\delta_{jk}+i\varepsilon_{jkl}\sigma_l$', r'cos/sin form of $U$', r'$U\tilde xU^\dagger$ is Rodrigues’ rotation by $\omega$', r'$U(2\pi)=-I$']),
 Q(4, '3D oscillator and su(3)', 'harmonic-oscillator-elevator', ['qm-ho-L4', 'qm-ho-c4', 'qm-am-c3', 'qm-am-L1'],
   r'$H=\hbar\omega(a_1^\dagger a_1+a_2^\dagger a_2+a_3^\dagger a_3+\frac32)$. (i) Show $J_{ij}=a_i^\dagger a_j$ is conserved and $E_{ij}\mapsto J_{ij}$ is a Lie algebra isomorphism from u(3). (ii) For su(3) with $h_1=E_{11}-E_{22}$, $h_2=E_{22}-E_{33}$, $e_1=E_{12}$, $e_2=E_{23}$, $e_3=E_{13}$, $f_i=e_i^T$: compute $\mathrm{ad}_{h_i}$, the roots $\Delta_\pm$, and the su(2) subalgebras. (iii) Highest-weight theory of irreps. (iv) Show that the degenerate eigenspaces of $H$ are su(3) irreps and give their highest weight.',
   [('(i) Conservation and isomorphism.', r'$[H,a_i^\dagger a_j]=\hbar\omega(a_i^\dagger a_j-a_i^\dagger a_j)=0$. $[E_{ij},E_{kl}]=\delta_{jk}E_{il}-\delta_{il}E_{kj}$ and $[a_i^\dagger a_j,a_k^\dagger a_l]=\delta_{jk}a_i^\dagger a_l-\delta_{il}a_k^\dagger a_j$: the same bracket.'),
    ('(ii) Roots.', r'$[h_1,e_1]=2e_1$, $[h_2,e_1]=-e_1$: root $(2,-1)$; $e_2$: $(-1,2)$; $e_3$: $(1,1)$; the $f$’s have the negatives. Each positive root gives $\{e_\alpha,h_\alpha=[e_\alpha,f_\alpha],f_\alpha\}\cong$ su(2) (e.g. $e_3,h_1+h_2,f_3$).'),
    ('(iii) Highest weight.', r'A finite irrep has a weight vector $v$ killed by all $e_\alpha$ (otherwise the weights would grow without bound); $V$ is spanned by the $f$’s acting on $v$. Restricting to each su(2) subalgebra forces $\lambda(h_\alpha)\in\mathbb Z_{\ge0}$. The adjoint rep has highest weight vector $e_3$, weight $(1,1)$.'),
    ('(iv) The oscillator levels.', r'Level $N$ = all $|n_1,n_2,n_3\rangle$ with $\sum n_i=N$, dimension $\frac{(N+1)(N+2)}{2}$. Highest weight vector $(a_1^\dagger)^N|0\rangle$, weight $(N,0)$: the symmetric irrep $\mathrm{Sym}^N(\mathbb C^3)$; su(3) explains the full degeneracy (more than SO(3) alone).')],
   [r'$[H,a_i^\dagger a_j]=0$ and matching brackets', r'roots $(2,-1),(-1,2),(1,1)$ and negatives', r'highest weight with integer $\lambda(h_\alpha)$', r'level $N$ = irrep with highest weight $(N,0)$']),
])
